#pragma once#include <io.h>class KDirCreator{  LPSTR m_pszNext;  char m_oldChar;public:  KDirCreator( LPSTR pszDirOut, size_t size, LPCSTR pszAddDir )    : m_pszNext( NULL )    , m_oldChar( 0 )  {    if( !(pszAddDir && *pszAddDir) )    {      int t = _access( pszDirOut, 0 );      if( t )        CreateDirectory( pszDirOut, NULL );      return;    }    size_t L = strlen( pszDirOut );    m_pszNext = &pszDirOut[L];    m_oldChar = *m_pszNext;    size_t leftSize = size - L;    if( '\\'!=m_pszNext[-1] && '/'!=m_pszNext[-1] )    {      strcpy_s( m_pszNext, leftSize, "/" );      strcat_s( m_pszNext, leftSize, pszAddDir );    }    else      strcpy_s( m_pszNext, leftSize, pszAddDir );    int t = _access( pszDirOut, 0 );    if( t )      CreateDirectory( pszDirOut, NULL );    strcat_s( pszDirOut, size, "/");  }  ~KDirCreator()  {    if( m_pszNext )      *m_pszNext = m_oldChar;  }    protected:  KDirCreator(){}};class KFileCreator{  LPSTR m_pszNext;  char m_oldChar;public:  KFileCreator( LPSTR pszDirOut, size_t size, LPCSTR pszAddFile, LPCSTR pszExt )  {    size_t L = strlen( pszDirOut );    m_pszNext = &pszDirOut[L];    m_oldChar = *m_pszNext;    size_t leftSize = size - L;    if( L > 3 && ('\\'!=m_pszNext[-1] && '/'!=m_pszNext[-1] ) )    {      strcpy_s( m_pszNext, leftSize, "/" );      strcat_s( m_pszNext, leftSize, pszAddFile );    }    else      strcpy_s( m_pszNext, leftSize, pszAddFile );    if( !pszExt || !*pszExt )      return;    if( '.'!=*pszExt )      strcat_s( m_pszNext, leftSize, "." );    strcat_s( m_pszNext, leftSize, pszExt );  }  ~KFileCreator()  {    *m_pszNext = m_oldChar;  }protected:  KFileCreator(){}};